from __future__ import annotations
import csv,json,os,threading,time,webbrowser
from datetime import datetime
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse
ROOT=Path(os.environ.get('THE_JOCKEY_RESEARCH_ROOT',Path.home()/'Downloads'/'THE-JOCKEY-RESEARCH'));HOST='127.0.0.1';PORT=int(os.environ.get('THE_JOCKEY_DASHBOARD_PORT','8791'))
def rj(p,d=None):
 try:return json.loads(p.read_text(encoding='utf-8-sig'))
 except:return d
def rc(p):
 try:
  with p.open('r',encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
 except:return []
def tail(p,n=80):
 try:return p.read_text(encoding='utf-8',errors='replace').splitlines()[-n:]
 except:return []
def build():
 core=ROOT/'CORE';reports=core/'reports';data=core/'data';program=rj(core/'program.json',{}) or {};missions=program.get('missions',[]);current=next((m for m in missions if str(m.get('state','')).upper()=='READY'),next((m for m in missions if str(m.get('state','')).upper()=='PENDING'),None));complete=sum(str(m.get('state','')).upper()=='COMPLETE' for m in missions)
 pop={'JRA':{},'NAR':{}}
 for x in rc(data/'CORE-001_domestic_population_audit.csv'):
  if x.get('domain') in pop and x.get('race_year')=='9999':pop[x['domain']]=x
 leakage={x.get('safety_class','UNKNOWN'):{'columns':int(float(x.get('columns',0) or 0)),'tables':int(float(x.get('tables',0) or 0))} for x in rc(reports/'CORE-002_feature_contract_summary_v2.csv')}
 sup=rj(ROOT/'checkpoints'/'autonomy_supervisor_state.json',{}) or {};domain=rj(ROOT/'checkpoints'/'domain_research_director_state.json',{}) or {};ensemble=rj(ROOT/'checkpoints'/'ensemble_director_state.json',{}) or {};meta=rj(ROOT/'checkpoints'/'meta_research_director_state.json',{}) or {};feature=rj(ROOT/'checkpoints'/'feature_research_director_state.json',{}) or {};prob=rj(ROOT/'checkpoints'/'probability_director_state.json',{}) or {}
 logs=[]
 for p in [ROOT/'logs'/'research_director.log',ROOT/'logs'/'probability_director.log',ROOT/'logs'/'meta_research_director.log',ROOT/'logs'/'feature_research_director.log',ROOT/'logs'/'domain_research_director.log',ROOT/'logs'/'ensemble_director.log',ROOT/'logs'/'autonomy_supervisor.log',ROOT/'logs'/'lab_updater.log']:
  for line in tail(p,18):logs.append({'source':p.name,'line':line})
 return {'project':'THE JOCKEY 完全自律研究所','updated':datetime.now().astimezone().isoformat(),'current':current,'missions':missions,'progress':{'complete':complete,'total':len(missions),'pct':round(complete/len(missions)*100,1) if missions else 0},'population':pop,'leakage':leakage,'supervisor':sup,'workers':{'Probability':prob,'Meta Improve':meta,'Feature Research':feature,'Domain JRA/NAR':domain,'Ensemble':ensemble},'production':sup.get('production',{}),'quality':sup.get('data_quality',{}),'drift':sup.get('drift',{}),'logs':logs[-120:]}
HTML='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>THE JOCKEY 完全自律研究所</title><style>:root{--b:#091018;--p:#111a24;--l:#263747;--t:#edf4fa;--m:#91a5b5;--g:#59d98e;--w:#f2c85b;--r:#ff7070;--i:#67aaff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#070b10,#101923);color:var(--t);font-family:Segoe UI,"Yu Gothic UI",sans-serif}header{padding:16px 22px;border-bottom:1px solid var(--l);display:flex;justify-content:space-between;position:sticky;top:0;background:#091018ee}main{max-width:1500px;margin:auto;padding:16px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px}.c{background:var(--p);border:1px solid var(--l);border-radius:14px;padding:15px}.s12{grid-column:span 12}.s8{grid-column:span 8}.s6{grid-column:span 6}.s4{grid-column:span 4}.big{font-size:27px;font-weight:700}.muted{color:var(--m);font-size:12px}.metric{display:flex;justify-content:space-between;border-bottom:1px dashed #263747;padding:7px 0}.g{color:var(--g)}.w{color:var(--w)}.r{color:var(--r)}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #263747;text-align:left}.log{height:260px;overflow:auto;background:#070c11;padding:10px;border-radius:10px;font:12px Consolas,monospace}@media(max-width:850px){.s8,.s6,.s4{grid-column:span 12}}</style></head><body><header><b>THE JOCKEY｜完全自律研究所</b><span id="updated" class="muted"></span></header><main><div class="grid"><section class="c s8"><div class="muted">CURRENT MISSION</div><div id="mission" class="big"></div><div id="progress" class="muted"></div></section><section class="c s4"><div class="muted">AUTONOMY STATUS</div><div id="auto" class="big"></div><div id="prod" class="muted"></div></section><section class="c s4"><b>Data Quality</b><div id="quality"></div></section><section class="c s4"><b>Drift</b><div id="drift"></div></section><section class="c s4"><b>Production Gate</b><div id="production"></div></section><section class="c s6"><b>AI Workers</b><div id="workers"></div></section><section class="c s6"><b>JRA / NAR</b><div id="domains"></div></section><section class="c s12"><b>Mission DAG</b><table><thead><tr><th>Mission</th><th>状態</th><th>内容</th></tr></thead><tbody id="missions"></tbody></table></section><section class="c s12"><b>Latest Autonomous Logs</b><div id="logs" class="log"></div></section></div></main><script>const m=(k,v,c='')=>`<div class="metric"><span>${k}</span><b class="${c}">${v??'-'}</b></div>`;const cls=s=>['PASS','READY','RUNNING','COMPLETE','RESTARTED'].includes(String(s).toUpperCase())?'g':(['WAITING','HOLD','PENDING','ALERT'].includes(String(s).toUpperCase())?'w':'r');async function go(){try{let s=await (await fetch('/api/state',{cache:'no-store'})).json();updated.textContent=new Date(s.updated).toLocaleString('ja-JP');mission.textContent=s.current?s.current.id:'QUEUE COMPLETE';progress.textContent=`${s.progress.complete}/${s.progress.total} COMPLETE (${s.progress.pct}%)`;let as=s.supervisor?.status||'WAITING';auto.textContent=as;auto.className='big '+cls(as);prod.textContent='Founder Action: '+((s.production?.status==='READY')?'なし':'監視中');quality.innerHTML=m('Status',s.quality?.status,cls(s.quality?.status))+m('Duplicate RHID',s.quality?.duplicate_race_horse_id??'-')+m('Label violations',s.quality?.label_order_violations??'-');drift.innerHTML=m('Status',s.drift?.status,cls(s.drift?.status))+m('Alerts',(s.drift?.alerts||[]).join(', ')||'なし');production.innerHTML=m('Prediction Model',s.production?.status,cls(s.production?.status))+m('Auto Betting','DISABLED','w');workers.innerHTML=Object.entries(s.workers||{}).map(([k,v])=>m(k,v.status||'WAITING',cls(v.status))).join('');let w=s.supervisor?.workers||{};workers.innerHTML+=Object.entries(w).map(([k,v])=>m(k.replace('.py',''),v.status,cls(v.status))).join('');domains.innerHTML=m('JRA races',s.population?.JRA?.race_count||'-')+m('NAR races',s.population?.NAR?.race_count||'-')+m('Domain Models',s.workers?.['Domain JRA/NAR']?.models||0,'g')+m('Ensembles',s.workers?.Ensemble?.ensembles||0,'g');missions.innerHTML=(s.missions||[]).map(x=>`<tr><td>${x.id||'-'}</td><td class="${cls(x.state)}">${x.state||'-'}</td><td>${x.name||''}</td></tr>`).join('');logs.innerHTML=(s.logs||[]).map(x=>`<div><span style="color:#607487">[${x.source}]</span> ${String(x.line).replaceAll('&','&amp;').replaceAll('<','&lt;')}</div>`).join('')}catch(e){auto.textContent='ERROR';auto.className='big r'}}go();setInterval(go,5000)</script></body></html>'''
class H(BaseHTTPRequestHandler):
 def sendx(self,status,ct,b):self.send_response(status);self.send_header('Content-Type',ct);self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  p=urlparse(self.path).path
  if p=='/api/state':self.sendx(200,'application/json; charset=utf-8',json.dumps(build(),ensure_ascii=False).encode())
  elif p in ('/','/index.html'):self.sendx(200,'text/html; charset=utf-8',HTML.encode())
  elif p=='/health':self.sendx(200,'text/plain; charset=utf-8',b'ok')
  else:self.sendx(404,'text/plain',b'not found')
 def log_message(self,*a):return
def op():time.sleep(.7);webbrowser.open(f'http://{HOST}:{PORT}')
if __name__=='__main__':
 if not ROOT.exists():raise SystemExit(f'Research root not found: {ROOT}')
 print('='*68);print(' THE JOCKEY 完全自律研究所 Dashboard');print('='*68);print(f'Research root : {ROOT}');print(f'Dashboard     : http://{HOST}:{PORT}');print('Ctrl+Cで停止');threading.Thread(target=op,daemon=True).start();ThreadingHTTPServer((HOST,PORT),H).serve_forever()
